repairs.css:
/* WordPress block adapter for Boogie Bar source selectors. Scoped to existing section classes. */
.site-header .wp-block-buttons,
.hero-inner > .wp-block-buttons,
.feature-event .wp-block-buttons,
.visit-card > .wp-block-buttons {
  margin: 0;
}

.site-header .wp-block-button,
.hero-inner .wp-block-button,
.feature-event .wp-block-button,
.visit-card .wp-block-button {
  margin: 0;
}

/* Header: convert WP button groups back into brand + nav links. */
.site-header > .wp-block-buttons {
  display: flex;
  align-items: center;
  gap: clamp(0.45rem, 1.6vw, 1.3rem);
}

.site-header > .wp-block-buttons:first-child .wp-block-button__link {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  min-height: 42px;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--ink) !important;
  font-size: 0;
  line-height: 1;
  text-transform: none;
}

.site-header > .wp-block-buttons:first-child .wp-block-button__link::before {
  content: "BB";
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  color: #13001f;
  font-family: "Cooper Black", "Bookman Old Style", Georgia, serif;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: -0.08em;
  background: conic-gradient(from 180deg, var(--acid), var(--laser-blue), var(--hot-pink), var(--orange), var(--acid));
  box-shadow: var(--shadow-pink), var(--shadow-blue);
}

.site-header > .wp-block-buttons:first-child .wp-block-button__link::after {
  content: "boogie bar";
  font-family: "Cooper Black", "Bookman Old Style", Georgia, serif;
  font-size: clamp(1.15rem, 2vw, 1.6rem);
  letter-spacing: -0.04em;
  text-transform: lowercase;
  text-shadow: 0 0 14px rgba(255, 47, 207, 0.8);
}

.site-header > .wp-block-buttons:nth-child(2) .wp-block-button__link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: auto;
  padding: 0.65rem 0.85rem !important;
  border: 0 !important;
  border-radius: 999px !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--muted) !important;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
}

.site-header > .wp-block-buttons:nth-child(2) .wp-block-button__link:hover {
  color: var(--ink) !important;
  background: rgba(255, 255, 255, 0.08) !important;
}

/* Hero and visit CTAs: map WP button links to source .button styles. */
.hero-inner > .wp-block-buttons,
.visit-card > .wp-block-buttons {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.9rem;
}

.visit-card > .wp-block-buttons {
  justify-content: flex-start;
}

.hero-inner > .wp-block-buttons .wp-block-button__link,
.visit-card > .wp-block-buttons .wp-block-button__link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  padding: 0.85rem 1.35rem !important;
  border-radius: 999px !important;
  border: 0;
  font-size: 0.82rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
  box-shadow: none;
}

.hero-inner > .wp-block-buttons .wp-block-button:first-child .wp-block-button__link,
.visit-card > .wp-block-buttons .wp-block-button__link {
  color: #15001f !important;
  background: linear-gradient(135deg, var(--acid), var(--laser-blue) 48%, var(--hot-pink)) !important;
  box-shadow: var(--shadow-pink), var(--shadow-blue) !important;
}

.hero-inner > .wp-block-buttons .wp-block-button:last-child .wp-block-button__link {
  color: var(--ink) !important;
  border: 1px solid rgba(255, 255, 255, 0.25) !important;
  background: rgba(255, 255, 255, 0.08) !important;
  box-shadow: inset 0 0 22px rgba(255, 255, 255, 0.05) !important;
}

/* Featured event booking link should be a small text link, not a white WP button. */
.feature-event .wp-block-buttons {
  display: block;
  margin-top: auto;
}

.feature-event .wp-block-button__link {
  display: inline !important;
  min-height: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--acid) !important;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
}

/* Hero detail card adapter for paragraph-based block structure. */
.hero-card-details {
  display: grid;
  gap: 0.65rem;
  margin: 0;
}

.hero-card-detail {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-top: 0.65rem;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
}

.hero-card-detail p {
  margin: 0;
}

.hero-card-detail .detail-label {
  color: var(--muted);
}

.hero-card-detail .detail-value {
  margin-left: auto;
  font-weight: 800;
  text-align: right;
}

/* Empty WP decorative cassette window needs pseudo reels. */
.cassette-window::before,
.cassette-window::after {
  content: "";
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.34);
  background: radial-gradient(circle, var(--chrome) 0 14%, transparent 15% 32%, var(--chrome) 33% 36%, transparent 37% 100%);
}

/* Override core Columns defaults for source grid geometry. */
.event-strip.wp-block-columns {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 1rem;
}

.menu-grid.wp-block-columns {
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: stretch;
  gap: 1rem;
}

.event-strip.wp-block-columns > .wp-block-column,
.menu-grid.wp-block-columns > .wp-block-column {
  display: block !important;
  flex-basis: auto !important;
  flex-grow: 0 !important;
  min-width: 0;
}

.event-strip .event-card,
.menu-grid .drink-card {
  height: 100%;
}

/* Track badges are paragraphs in WP output, spans in source. */
.track-list p {
  display: inline-flex;
  align-items: center;
  margin: 0;
  padding: 0.45rem 0.65rem;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.05);
  font-size: 0.78rem;
  line-height: 1;
}

/* Contact grid adapter for WP Columns wrappers. */
.contact-grid.wp-block-columns {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.contact-grid.wp-block-columns > .wp-block-column {
  display: block !important;
  flex-basis: auto !important;
  min-width: 0;
}

.contact-grid p {
  margin: 0;
}

@media (max-width: 760px) {
  .site-header {
    top: 8px;
    width: min(calc(100% - 12px), 360px);
    padding: 6px 8px;
  }

  .site-header > .wp-block-buttons:nth-child(2) {
    display: none !important;
  }

  .site-header > .wp-block-buttons:first-child .wp-block-button__link::before {
    width: 28px;
    height: 28px;
    font-size: 0.72rem;
  }

  .site-header > .wp-block-buttons:first-child .wp-block-button__link::after {
    font-size: 0.9rem;
  }

  .event-strip.wp-block-columns,
  .menu-grid.wp-block-columns {
    grid-template-columns: 1fr;
  }

  .hero-inner > .wp-block-buttons {
    gap: 0.55rem;
  }

  .hero-inner > .wp-block-buttons .wp-block-button__link,
  .visit-card > .wp-block-buttons .wp-block-button__link {
    min-height: 46px;
    padding: 0.78rem 1rem !important;
    font-size: 0.72rem;
  }

  .contact-grid.wp-block-columns {
    grid-template-columns: 1fr;
  }
}

/* Repair 2: mobile/component refinements for remaining WordPress wrapper drift */

/* Price is rendered as a paragraph in WP; force it to behave like the source span badge. */
.drink-card {
  position: relative !important;
  overflow: hidden;
}

.drink-card .drink-price {
  position: absolute !important;
  top: 16px !important;
  right: 16px !important;
  left: auto !important;
  bottom: auto !important;
  z-index: 5;
  display: grid !important;
  place-items: center;
  width: 38px;
  height: 38px;
  min-width: 38px;
  min-height: 38px;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 999px;
  background: #fff6ff !important;
  color: #16002d !important;
  font-size: 0.68rem;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.02em;
  box-shadow: 0 0 20px rgba(255, 246, 255, 0.38);
}

.drink-card h3 {
  padding-right: 3rem;
}

@media (max-width: 700px) {
  /* Normalize WP Columns wrappers to the source mobile geometry. */
  .event-strip.wp-block-columns,
  .menu-grid.wp-block-columns {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 1rem !important;
    width: 100%;
  }

  .contact-grid.wp-block-columns {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 0.7rem !important;
    width: 100%;
  }

  .event-strip.wp-block-columns > .wp-block-column,
  .menu-grid.wp-block-columns > .wp-block-column,
  .contact-grid.wp-block-columns > .wp-block-column {
    flex-basis: auto !important;
    flex-grow: 0 !important;
    width: auto !important;
    min-width: 0;
    margin: 0 !important;
  }

  .event-card,
  .drink-card {
    width: 100%;
  }

  .drink-card .drink-price {
    top: 14px !important;
    right: 14px !important;
    width: 36px;
    height: 36px;
    min-width: 36px;
    min-height: 36px;
    font-size: 0.64rem;
  }

  .drink-card h3 {
    padding-right: 2.75rem;
  }

  /* Keep the Visit CTA at the source mobile pill scale. */
  .visit-card > .wp-block-buttons {
    display: flex !important;
    width: 100%;
    margin-top: 0.9rem;
  }

  .visit-card > .wp-block-buttons > .wp-block-button {
    flex: 1 1 100%;
    width: 100%;
  }

  .visit-card > .wp-block-buttons .wp-block-button__link {
    width: 100%;
    min-height: 42px;
    padding: 0.78rem 1rem;
    justify-content: center;
  }

  /* Small hero normalization only on mobile; desktop is already within tolerance. */
  .hero {
    display: block !important;
    min-height: 0;
    padding-top: 76px;
    padding-bottom: 34px;
  }

  .hero-inner {
    width: 100%;
    margin: 0 auto;
  }

  .hero h1 {
    max-width: 360px;
    margin-top: 0.12em;
    margin-bottom: 0.24em;
    font-size: clamp(3rem, 13.4vw, 3.45rem);
    line-height: 0.78;
  }

  .hero-copy {
    max-width: 310px;
    margin-bottom: 0.85rem;
    font-size: 0.82rem;
    line-height: 1.35;
  }

  .hero-inner .wp-block-buttons {
    justify-content: center;
    flex-wrap: nowrap;
    gap: 0.55rem;
  }

  .hero-inner .wp-block-button__link {
    min-height: 34px;
    padding: 0.55rem 0.82rem;
    font-size: 0.58rem;
    white-space: nowrap;
  }

  .hero-card {
    position: relative !important;
    right: auto !important;
    bottom: auto !important;
    width: 100% !important;
    max-width: 358px;
    margin: 1.05rem auto 0;
  }

  .track-list p {
    margin: 0 !important;
  }
}

/* Repair pass 2: scoped WP wrapper adapter for remaining mobile/component drift. */

/* The source price is a positioned badge. In WP it is a paragraph, so remove it
   from paragraph flow and pin it to the card corner. */
.drinks .drink-card {
  position: relative;
  overflow: hidden;
}

.drinks .drink-card .drink-price,
.drinks .drink-card p.drink-price {
  position: absolute !important;
  top: 1rem !important;
  right: 1rem !important;
  left: auto !important;
  z-index: 4 !important;
  display: grid !important;
  place-items: center !important;
  width: 38px !important;
  height: 38px !important;
  min-width: 38px !important;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 999px !important;
  background: #fff6ff !important;
  color: #170020 !important;
  font-size: 0.72rem !important;
  line-height: 1 !important;
  font-weight: 900 !important;
  letter-spacing: -0.03em !important;
  box-shadow: 0 0 18px rgba(255, 246, 255, 0.42) !important;
}

.drinks .drink-card h3 {
  margin-top: 7.05rem !important;
}

/* Keep track-list pills compact when rendered as WP paragraphs. */
.soundtrack .track-list > p {
  margin: 0 !important;
}

@media (max-width: 700px) {
  /* Source mobile stacks the cocktail cards as full-width cards with a stable
     card height; WP columns/paragraph flow made them visually compressed. */
  .drinks .menu-grid,
  .drinks .wp-block-columns.menu-grid {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 0.9rem !important;
    align-items: stretch !important;
  }

  .drinks .menu-grid > .wp-block-column {
    flex-basis: auto !important;
    width: auto !important;
    margin: 0 !important;
  }

  .drinks .drink-card {
    min-height: 228px !important;
    padding: 1.25rem 1.25rem 1.2rem !important;
  }

  .drinks .drink-card h3 {
    margin-top: 7.15rem !important;
  }

  .drinks .drink-card p:not(.drink-price) {
    margin-bottom: 0 !important;
  }

  .drinks .drink-card .drink-price,
  .drinks .drink-card p.drink-price {
    top: 0.9rem !important;
    right: 0.9rem !important;
    width: 36px !important;
    height: 36px !important;
    min-width: 36px !important;
    font-size: 0.68rem !important;
  }

  /* Preserve the compact source contact grid instead of inheriting core/columns
     mobile stacking and paragraph margins. */
  .visit .contact-grid,
  .visit .wp-block-columns.contact-grid {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 0.65rem !important;
    align-items: stretch !important;
  }

  .visit .contact-grid > .wp-block-column {
    flex-basis: auto !important;
    width: auto !important;
    margin: 0 !important;
    min-width: 0 !important;
  }

  .visit .contact-grid p {
    margin: 0 !important;
  }
}

@media (max-width: 430px) {
  .visit .contact-grid,
  .visit .wp-block-columns.contact-grid {
    gap: 0.55rem !important;
  }

  .visit .contact-grid > .wp-block-column {
    padding-inline: 0.65rem !important;
  }
}

/* Repair pass 3: recover mobile component scale without disturbing the close desktop layout. */
.drink-card {
  position: relative;
}

.drink-card > p.drink-price {
  position: absolute !important;
  top: clamp(0.75rem, 1.4vw, 1rem) !important;
  right: clamp(0.75rem, 1.4vw, 1rem) !important;
  left: auto !important;
  bottom: auto !important;
  transform: none !important;
  z-index: 6;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 999px;
  background: #fff6ff;
  color: #16002d;
  font-weight: 900;
  font-size: 0.72rem;
  line-height: 1;
  letter-spacing: -0.03em;
  box-shadow: 0 0 22px rgba(255, 246, 255, 0.38);
}

@media (max-width: 640px) {
  .hero-inner > .wp-block-buttons {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 0.65rem;
    width: min(100%, 322px);
    margin: 0 auto !important;
    align-items: stretch;
    justify-content: center;
  }

  .hero-inner > .wp-block-buttons > .wp-block-button {
    width: 100%;
    min-width: 0;
  }

  .hero-inner > .wp-block-buttons .wp-block-button__link {
    width: 100%;
    min-width: 0;
    min-height: 30px;
    padding: 0.52rem 0.55rem;
    font-size: 0.62rem;
    line-height: 1;
    white-space: nowrap;
  }

  .drink-card > p.drink-price {
    top: 0.78rem !important;
    right: 0.78rem !important;
    width: 34px;
    height: 34px;
    font-size: 0.64rem;
  }

  .visit-card > .wp-block-buttons {
    display: block !important;
    width: 100%;
    margin-top: 1rem;
  }

  .visit-card > .wp-block-buttons > .wp-block-button {
    display: block;
    width: 100%;
  }

  .visit-card > .wp-block-buttons .wp-block-button__link {
    width: 100%;
    min-height: 34px;
    padding: 0.62rem 1rem;
  }
}

@media (max-width: 600px) {
  .wp-block-group.hero {
    min-height: auto !important;
    padding: 4.15rem 0.75rem 3.15rem !important;
    display: block !important;
    place-items: initial !important;
  }

  .hero-inner {
    width: 100% !important;
    max-width: 22rem !important;
    margin: 0 auto !important;
    text-align: center !important;
  }

  .hero-kicker,
  .eyebrow,
  .card-label,
  .event-date {
    font-size: 0.58rem !important;
    line-height: 1.1 !important;
    letter-spacing: 0.17em !important;
  }

  .hero h1 {
    max-width: 20.5rem !important;
    margin: 0.08em auto 0.28em !important;
    font-size: clamp(2.78rem, 13.2vw, 3.32rem) !important;
    line-height: 0.76 !important;
    letter-spacing: -0.078em !important;
  }

  .hero-copy {
    max-width: 18.5rem !important;
    margin: 0 auto 0.78rem !important;
    font-size: 0.68rem !important;
    line-height: 1.32 !important;
  }

  .hero .wp-block-buttons,
  .visit-card .wp-block-buttons,
  .feature-event .wp-block-buttons {
    margin: 0 !important;
    gap: 0.45rem !important;
    justify-content: center !important;
    align-items: center !important;
  }

  .hero .wp-block-button__link,
  .visit-card .wp-block-button__link,
  .feature-event .wp-block-button__link {
    min-height: 1.78rem !important;
    padding: 0.42rem 0.82rem !important;
    font-size: 0.52rem !important;
    line-height: 1 !important;
    white-space: nowrap !important;
  }

  .hero-card {
    position: relative !important;
    inset: auto !important;
    width: calc(100vw - 1.5rem) !important;
    max-width: 23rem !important;
    margin: 0.78rem auto 0 !important;
    padding: 0.82rem 0.92rem !important;
    border-radius: 16px !important;
  }

  .card-title {
    margin: 0.18rem 0 0.55rem !important;
    font-size: 1.08rem !important;
    line-height: 0.95 !important;
  }

  .hero-card-details {
    display: grid !important;
    gap: 0 !important;
  }

  .hero-card-detail {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 0.75rem !important;
    padding: 0.34rem 0 0 !important;
    margin: 0.34rem 0 0 !important;
    border-top: 1px solid rgba(255, 255, 255, 0.14) !important;
  }

  .hero-card-detail p,
  .detail-label,
  .detail-value {
    margin: 0 !important;
    font-size: 0.62rem !important;
    line-height: 1.2 !important;
  }

  .hero::before {
    height: 8.25rem !important;
    transform: perspective(270px) rotateX(62deg) translateY(1.8rem) !important;
  }

  .hero-orbit-one {
    width: 10.25rem !important;
    height: 10.25rem !important;
    left: -4.65rem !important;
    top: 3.35rem !important;
  }

  .hero-orbit-two {
    width: 5.85rem !important;
    height: 5.85rem !important;
    right: -1.15rem !important;
    top: 4.1rem !important;
  }

  .intro,
  .saturdays,
  .soundtrack,
  .drinks,
  .booths,
  .visit,
  .site-footer {
    padding-left: 0.85rem !important;
    padding-right: 0.85rem !important;
  }

  .intro {
    display: block !important;
    padding-top: 2.05rem !important;
    padding-bottom: 2.95rem !important;
  }

  .section-number {
    margin: 0 0 0.85rem !important;
    font-size: 1.88rem !important;
    line-height: 1 !important;
  }

  .intro-content,
  .wide-heading,
  .soundtrack-copy,
  .drinks-header,
  .booth-copy,
  .visit-card {
    max-width: none !important;
  }

  .intro h2,
  .wide-heading h2,
  .soundtrack h2,
  .drinks-header h2,
  .booth-copy h2,
  .visit-card h2 {
    font-size: clamp(2rem, 10.2vw, 2.46rem) !important;
    line-height: 0.82 !important;
    letter-spacing: -0.06em !important;
  }

  .intro-content p:not(.eyebrow),
  .soundtrack-copy > p:not(.eyebrow),
  .booth-copy > p:not(.eyebrow),
  .visit-card > p:not(.eyebrow),
  .event-card p,
  .drink-card p {
    font-size: 0.69rem !important;
    line-height: 1.32 !important;
  }

  .intro-panel {
    margin-top: 1.05rem !important;
    min-height: 9.85rem !important;
    padding: 0.62rem !important;
    border-radius: 18px !important;
  }

  .panel-dancefloor {
    min-height: 5.95rem !important;
    border-radius: 12px !important;
  }

  .panel-copy {
    margin-top: 0.48rem !important;
  }

  .panel-title,
  .panel-description {
    margin: 0 !important;
  }

  .panel-title {
    font-size: 0.72rem !important;
    line-height: 1.1 !important;
  }

  .panel-description {
    margin-top: 0.18rem !important;
    font-size: 0.6rem !important;
    line-height: 1.25 !important;
  }

  .saturdays {
    padding-top: 2.55rem !important;
